def score(program: str) -> float:
    functions = program.count('def ')
    returns = program.count('return ')

    if functions == 1 and returns == 1:
        return 1.0

    delta = abs(functions - 1) + abs(returns - 1)
    return max(0.0, min(1.0, 0.8 - delta * 0.1))

